/bin/bash -lc "python - <<'PY'
from decimal import Decimal
counts = {}
with open('/workspace/galaxy_outputs/jd_site_counts_corrected.tabular', encoding='utf-8') as fh:
    for line in fh:
        fields = line.rstrip('\\n').split('\\t')
        if len(fields) >= 2 and fields[0].isdigit():
            counts[fields[1]] = int(fields[0])
lengths = {}
with open('/workspace/galaxy_outputs/jd_lengths_tabular.tabular', encoding='utf-8-sig') as fh:
    next(fh)
    for line in fh:
        fields = line.rstrip('\\n').split('\\t')
        if len(fields) >= 2:
            lengths[fields[0]] = int(fields[1])
rows = [(Decimal(n)/Decimal(lengths[c]), c, n, lengths[c]) for c,n in counts.items() if c in lengths]
for density, chrom, n, length in sorted(rows, reverse=True)[:15]:
    print(f'{chrom}\\t{n}\\t{length}\\t{density}')
print('matched chromosomes:', len(rows))
PY"

